starter.variables.tf:
variable "bucket_name" {
  description = "Bucket name passed to the storage module."
  type        = string
  default     = "arena-tutorial-storage"
}

starter.main.tf:
module "storage" {
  source      = "./modules/storage"
  bucket_name = var.bucket_name
}

output "bucket_id" {
  # TODO - Wire the module output.
  # Set the root output value to the module's storage_id output.
}

starter.modules/storage/main.tf:
variable "bucket_name" {
  type = string
}

resource "terraform_data" "storage" {
  input = var.bucket_name
}

output "storage_id" {
  value = terraform_data.storage.id
}
